import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getKeyword, updateKeyword } from '../services/api';

const EditKeyword = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    image: null
  });
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchKeyword = async () => {
      try {
        const data = await getKeyword(id);
        setFormData({
          title: data.title,
          description: data.description,
          image: null
        });
        setPreview(data.imageUrl);
        setLoading(false);
      } catch (err) {
        setError('Failed to fetch keyword. Please try again later.');
        setLoading(false);
      }
    };

    fetchKeyword();
  }, [id]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setFormData({
        ...formData,
        image: file
      });

      // Create a preview URL for the selected image
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Basic validation
    if (!formData.title || !formData.description) {
      setError('Please fill in all required fields.');
      return;
    }

    setSubmitting(true);
    setError(null);

    try {
      const data = new FormData();
      data.append('title', formData.title);
      data.append('description', formData.description);

      if (formData.image) {
        data.append('image', formData.image);
      }

      await updateKeyword(id, data);
      navigate('/keywords');
    } catch (err) {
      setError('Failed to update keyword. Please try again.');
      setSubmitting(false);
    }
  };

  if (loading) {
    return <div className="loading">Loading keyword details...</div>;
  }

  if (error && !submitting) {
    return <div className="error-message">{error}</div>;
  }

  return (
    <div className="edit-keyword-page">
      <div className="header">
        <h1>Edit Keyword</h1>
      </div>

      <form className="edit-keyword-form" onSubmit={handleSubmit}>
        <h2 className="form-title">Keyword Details</h2>

        {error && <div className="error">{error}</div>}

        <div className="form-group">
          <label htmlFor="title">Title *</label>
          <input
            type="text"
            id="title"
            name="title"
            className="form-control"
            value={formData.title}
            onChange={handleChange}
            placeholder="Enter keyword title"
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="description">Description *</label>
          <textarea
            id="description"
            name="description"
            className="form-control"
            value={formData.description}
            onChange={handleChange}
            placeholder="Enter keyword description"
            rows="4"
            required
          ></textarea>
        </div>

        <div className="form-group">
          <label htmlFor="image">Background Image</label>
          <input
            type="file"
            id="image"
            name="image"
            className="form-control"
            onChange={handleImageChange}
            accept="image/*"
          />
          <small className="form-text">
            Upload a new image or leave empty to keep the current one. Max size: 5MB. Supported formats: JPEG, PNG, GIF.
          </small>
        </div>

        <div className="image-preview keyword-preview">
          {preview ? (
            <div 
              className="keyword-preview-content"
              style={{
                backgroundImage: `url(${preview})`,
                backgroundSize: 'cover',
                backgroundPosition: 'center'
              }}
            >
              <h2 className="keyword-title">{formData.title || 'Keyword Title'}</h2>
              <p className="keyword-description">{formData.description || 'Keyword description will appear here.'}</p>
            </div>
          ) : (
            <div className="image-preview-text">No image selected</div>
          )}
        </div>

        <div className="form-actions">
          <button 
            type="submit" 
            className="btn submit-btn" 
            disabled={submitting}
          >
            {submitting ? 'Updating...' : 'Update Keyword'}
          </button>
          <button 
            type="button" 
            className="btn btn-secondary" 
            onClick={() => navigate('/keywords')}
          >
            Cancel
          </button>
        </div>
      </form>
    </div>
  );
};

export default EditKeyword;
